import{_ as n,l as o,o as a,c as l,v as r,p as s,x as i,d as c,i as h,S as E}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"Heckscher–Ohlin","description":"","frontmatter":{"title":"Heckscher–Ohlin","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/heckscher-ohlin.md","filePath":"econ/heckscher-ohlin.md","lastUpdated":1789023840000}'),B={name:"econ/heckscher-ohlin.md"};function d(p,e,A,m,_,k){const t=o("Mermaid");return a(),l("div",null,[e[1]||(e[1]=r('<h1 id="heckscher–ohlin" tabindex="-1">Heckscher–Ohlin <a class="header-anchor" href="#heckscher–ohlin" aria-label="Permalink to &quot;Heckscher–Ohlin&quot;">​</a></h1><div class="epigraph"><p>技术相同、偏好相似时，一国出口密集使用其丰裕要素的产品；贸易是要素服务的间接流动，而不必把工人运出国境。</p><footer>—— Heckscher, The Effect of Foreign Trade on the Distribution of Income, 1919；Ohlin, Interregional and International Trade, 1933</footer></div><p><a href="/econ/ricardian-comparative-advantage">上一课</a>用劳动生产率差解释分工。本课缺口是：技术若相同，贸易从哪来？Heckscher–Ohlin（HO）用要素禀赋。Stolper–Samuelson 下一课把价格接到要素报酬；本课先钉 \\(2\\times2\\times2\\) 的出口模式。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>两国、两商品、两要素（资本与劳动），相同规模报酬不变技术、相同位似偏好。本国资本相对丰裕：\\(K/L\\gt K^*/L^*\\)。商品 1 资本密集。HO 定理：本国出口 1、进口 2。缺口不是再讲李嘉图的 \\(a_{Li}\\)，而是：相对禀赋差 → 封闭时相对要素价格差 → 相对商品价格差 → 贸易方向。要素不能跨境，商品贸易部分替代要素流动。</p><p><span class="marginnote">要素价格均等化（FPE）：自由贸易加要素密集不逆转、两国都生产两种商品，则 \\(w,r\\) 被商品价格钉死，与禀赋无关（在 FPE 集内）。禀赋只定产量，不定要素价格。这是强结论，实证上常破，但逻辑要先有。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>封闭：丰裕要素相对便宜，密集使用它的产品相对便宜。开放：该产品出口，直到商品价格对齐。Rybczynski：禀赋增加、商品价格不变时，密集使用该要素的产品产量升、另一种降——产量调整代替要素价格调整（在 FPE 内）。这是后课增长与移民的对照系。</p>',8)),(a(),s(E,null,{default:i(()=>[h(t,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20END%5B%22%E7%9B%B8%E5%AF%B9%E7%A6%80%E8%B5%8B%22%5D%20--%3E%20AUT%5B%22%E5%B0%81%E9%97%AD%E7%9B%B8%E5%AF%B9%E4%BB%B7%E6%A0%BC%22%5D%0A%20%20AUT%20--%3E%20TRADE%5B%22%E5%87%BA%E5%8F%A3%E4%B8%B0%E8%A3%95%E8%A6%81%E7%B4%A0%E5%AF%86%E9%9B%86%E5%93%81%22%5D%0A%20%20FPE%5B%22%E5%85%B1%E5%90%8C%E5%A4%9A%E6%A0%B7%E5%8C%96%22%5D%20--%3E%20EQ%5B%22%E8%A6%81%E7%B4%A0%E4%BB%B7%E6%A0%BC%E8%A2%AB%E5%95%86%E5%93%81%E4%BB%B7%E9%92%89%E6%AD%BB%22%5D%0A%20%20RYB%5B%22Rybczynski%22%5D%20--%3E%20Q%5B%22%E4%BA%A7%E9%87%8F%E8%B0%83%2C%20%E8%A6%81%E7%B4%A0%E4%BB%B7%E4%B8%8D%E8%B0%83%22%5D%0A"})]),fallback:i(()=>[...e[0]||(e[0]=[c(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=r('<p>Leontief 悖论：美国出口劳动密集——对 HO 的早期打击。读法包括：人力资本不是简单 \\(L\\)、技术不同（回到李嘉图）、需求差异、要素密集逆转。本课不仲裁数据，只要求：定理的假设清单要对照着读悖论。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是相对稀缺。商品流动带着要素服务。完全 FPE 时，贸易已经把要素价格拉齐，再让劳动移民的增益只剩不可贸易品与集聚——后课 Melitz、经济地理。FPE 失败（专业化到锥外、贸易成本、技术差）时，要素价格仍可差，移民与贸易是互补而不是完全替代。</p><p>与李嘉图：李嘉图是技术差、一种要素；HO 是技术同、多种要素。现实两者都在。不要用 HO 否定比较优势：HO 是比较优势的一种来源（禀赋），不是替代定义。</p><p><span class="marginnote">Ohlin 强调地区间要素流动与商品流动的替代。Heckscher 更早把收入分配写进贸易。Samuelson 把 \\(2\\times2\\) 代数写严。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>\\(2\\times2\\times2\\) 不能直接读成「资本丰裕国只出口机器」。多要素、多商品用 HOV（Vanek）写成要素含量：净出口的要素含量等于禀赋减消费的要素含量。Trefler 的「缺失贸易」：要素含量远小于禀赋差，要技术差与贸易成本。下一课 SS：商品价格变动如何切分 \\(w\\) 与 \\(r\\)，这是分配政治的理论核。</p><p>后课默认：技术相同时，出口丰裕要素的密集型产品；FPE 是共同多样化的强预测，不是数据默认。李嘉图的技术差与 HO 的禀赋差可以并存。不要用封闭要素价格当自由贸易后的工资。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>HO：出口密集使用丰裕要素的产品。</li><li>贸易替代（部分）要素流动；FPE 在锥内钉住 \\(w,r\\)。</li><li>Rybczynski：价格不变时产量随禀赋极端调整。</li><li>Leontief / 缺失贸易对照的是假设，不是「定理算错」。</li><li>出处：Heckscher 1919；Ohlin 1933；Samuelson 的 \\(2\\times2\\)；Vanek；Trefler。</li></ul>',10))])}const T=n(B,[["render",d]]);export{u as __pageData,T as default};
